// Fisher-Yates shuffle
function shuffle(arr) {
  const a = [...arr]
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[a[i], a[j]] = [a[j], a[i]]
  }
  return a
}

// Builds a fresh 50-question HSE exam, following the official topic
// distribution, with questions and their answer order both randomised —
// exactly like the real ECS assessment (which draws randomly from the bank
// and randomises answer order).
export function generateHseExam() {
  const byCategory = {}
  for (const q of hseQuestionBank) {
    if (!byCategory[q.categoryId]) byCategory[q.categoryId] = []
    byCategory[q.categoryId].push(q)
  }

  const selected = []
  for (const { categoryId, questionsInExam } of HSE_TOPIC_DISTRIBUTION) {
    const pool = shuffle(byCategory[categoryId] || [])
    selected.push(...pool.slice(0, questionsInExam))
  }

  const exam = shuffle(selected).map((q) => ({
    ...q,
    options: shuffle(q.options),
  }))

  return exam
}

// Builds a topic-focused practice set: EVERY official question from a
// single category, shuffled, with answer order shuffled too. Since this
// draws only from the real 327-question official bank, it's still 100%
// official ECS content — just filtered down to one topic so users can
// drill their weak areas.
export function generateHseTopicPractice(categoryId) {
  const pool = hseQuestionBank.filter((q) => q.categoryId === categoryId)
  return shuffle(pool).map((q) => ({
    ...q,
    options: shuffle(q.options),
  }))
}

// How many official questions exist per topic (useful for UI display).
export function getHseTopicQuestionCounts() {
  const counts = {}
  for (const q of hseQuestionBank) {
    counts[q.categoryId] = (counts[q.categoryId] || 0) + 1
  }
  return counts
}

